import type {
  AppState,
  Helper,
  ID,
  JiraSnapshot,
  JiraTeamSource,
  Plan,
  PlanViewMode,
  Project,
  SprintDraft,
  TaskItem,
  TeamInclusion,
  Tracker,
  TrackerDeadlines,
  TrackerSample,
} from "@planner/core";

export { newId } from "@planner/core";

/** Fields of a task the user can supply/edit (id is generated by the store). */
export type TaskInput = Omit<TaskItem, "id">;
export type TaskPatch = Partial<Omit<TaskItem, "id">>;

export type HelperInput = Omit<Helper, "id">;
export type HelperPatch = Partial<Omit<Helper, "id">>;
export type MemberPatch = Partial<{
  name: string;
  specialization: string;
  speed: number;
}>;

/** One person brought in from a Jira team (the store generates the id). */
export interface JiraMemberInput {
  name: string;
  specialization: string;
  jiraAccountId: string;
}

/** Fields of a team inclusion the UI can set (teamId identifies the entry). */
export type TeamInclusionPatch = Partial<Omit<TeamInclusion, "teamId">>;

/**
 * One row of a write-back result: the dates Jira accepted for an issue, and
 * when. Carried in the action rather than read from the clock so the reducer
 * stays pure — the caller already knows when the write landed.
 */
export type SprintItemApplied = {
  issueKey: string;
  at: string;
  startDate: string;
  dueDate: string;
};

export type Direction = -1 | 1; // -1 = move up/earlier, +1 = move down/later

/**
 * The full set of reducer actions. Ids for new entities are pre-generated by
 * the action creators in useAppStore() and carried in the action, so callers
 * can learn the id of what they just created (e.g. to navigate to it).
 */
export type Action =
  // whole-state replacements
  | { type: "hydrate"; state: AppState }
  | { type: "resetSample"; state: AppState }
  | { type: "importState"; state: AppState }
  // projects
  | { type: "createProject"; id: ID; name: string; startDate: string }
  | { type: "copyProject"; sourceId: ID; newId: ID }
  // A whole project built elsewhere (e.g. from a Jira initiative), ids and all.
  | { type: "addProject"; project: Project }
  | { type: "deleteProject"; id: ID }
  | { type: "renameProject"; id: ID; name: string }
  | { type: "setProjectStartDate"; id: ID; startDate: string }
  | { type: "setProjectNote"; id: ID; note: string }
  | { type: "setProjectTitleColor"; id: ID; color: string | null }
  | { type: "setProjectBuffer"; id: ID; buffer: number }
  // epics
  | { type: "addEpic"; projectId: ID; epicId: ID; name: string }
  | { type: "renameEpic"; projectId: ID; epicId: ID; name: string }
  | { type: "deleteEpic"; projectId: ID; epicId: ID }
  | { type: "reorderEpic"; projectId: ID; epicId: ID; direction: Direction }
  | {
      type: "toggleEpicAssignment";
      projectId: ID;
      epicId: ID;
      memberId: ID;
    }
  | {
      type: "toggleEpicDependency";
      projectId: ID;
      epicId: ID;
      dependsOnEpicId: ID;
    }
  // tasks
  | {
      type: "addTask";
      projectId: ID;
      epicId: ID;
      taskId: ID;
      task: TaskInput;
    }
  | {
      type: "editTask";
      projectId: ID;
      epicId: ID;
      taskId: ID;
      patch: TaskPatch;
    }
  | { type: "toggleTaskExcluded"; projectId: ID; epicId: ID; taskId: ID }
  | { type: "deleteTask"; projectId: ID; epicId: ID; taskId: ID }
  | {
      type: "reorderTask";
      projectId: ID;
      epicId: ID;
      taskId: ID;
      direction: Direction;
    }
  | {
      type: "moveTask";
      projectId: ID;
      epicId: ID;
      taskId: ID;
      toIndex: number;
    }
  | {
      type: "toggleTaskDependency";
      projectId: ID;
      epicId: ID;
      taskId: ID;
      dependsOnTaskId: ID;
    }
  | {
      /** Replace a task's whole dependency list (bulk select in the picker). */
      type: "setTaskDependencies";
      projectId: ID;
      epicId: ID;
      taskId: ID;
      dependsOnTaskIds: ID[];
    }
  // teams
  | { type: "addTeam"; id: ID; name: string }
  | { type: "renameTeam"; id: ID; name: string }
  | { type: "deleteTeam"; id: ID }
  /**
   * Create a team from Jira, or update one already imported: its Jira origin
   * is refreshed and the given people are appended. Nothing already on the
   * team is changed or removed — the roster here is Planner's own.
   */
  | {
      type: "importJiraTeam";
      teamId: ID;
      name: string;
      jira: JiraTeamSource;
      members: (JiraMemberInput & { id: ID })[];
    }
  // team members (member ids are globally unique; the reducer finds the team)
  | {
      type: "addTeamMember";
      teamId: ID;
      id: ID;
      name: string;
      specialization: string;
    }
  | { type: "editTeamMember"; id: ID; patch: MemberPatch }
  | { type: "deleteTeamMember"; id: ID }
  | { type: "toggleOffDay"; memberId: ID; dateISO: string }
  // per-project team inclusion
  | { type: "toggleTeamIncluded"; projectId: ID; teamId: ID }
  | {
      type: "updateTeamInclusion";
      projectId: ID;
      teamId: ID;
      patch: TeamInclusionPatch;
    }
  | { type: "toggleTeamInclusionEpic"; projectId: ID; teamId: ID; epicId: ID }
  // per-project helpers
  | {
      type: "addHelper";
      projectId: ID;
      helperId: ID;
      helper: HelperInput;
    }
  | {
      type: "editHelper";
      projectId: ID;
      helperId: ID;
      patch: HelperPatch;
    }
  | { type: "deleteHelper"; projectId: ID; helperId: ID }
  | {
      type: "setMemberStart";
      projectId: ID;
      memberId: ID;
      date: string | null;
    }
  // plan
  | { type: "setPlan"; projectId: ID; plan: Plan | null }
  | { type: "setPlanViewMode"; projectId: ID; mode: PlanViewMode }
  | {
      type: "setPlanMode";
      projectId: ID;
      mode: "balanced" | "smart";
      lookahead?: number;
    }
  // trackers (a whole tracker is one row, so every field lands in one action)
  | {
      type: "createTracker";
      id: ID;
      name: string;
      initiativeUrl: string;
      initiativeKey: string;
      baseUrl: string;
    }
  // A whole tracker, for flows that already hold its snapshot and mapping.
  | { type: "addTracker"; tracker: Tracker }
  | { type: "deleteTracker"; id: ID }
  | { type: "renameTracker"; id: ID; name: string }
  | { type: "setTrackerProject"; id: ID; projectId: ID | null }
  | { type: "setTrackerHoursPerDay"; id: ID; hoursPerDay: number | null }
  | { type: "setTrackerDeadlines"; id: ID; deadlines: TrackerDeadlines | null }
  | {
      type: "setTrackerEpicMap";
      id: ID;
      epicMap: { [jiraEpicKey: string]: ID | null };
    }
  | {
      type: "setTrackerTaskMap";
      id: ID;
      taskMap: { [jiraIssueKey: string]: ID | null };
    }
  | { type: "setTrackerUntrackedEpics"; id: ID; epicKeys: string[] }
  | { type: "setTrackerViewTeams"; id: ID; teamNames: string[] }
  | {
      type: "setTrackerTaskTeam";
      id: ID;
      issueKey: string;
      team: string | null;
    }
  | {
      type: "setTrackerAddedScope";
      id: ID;
      addedScope: { [jiraIssueKey: string]: string };
    }
  // One refresh yields both the snapshot and (once a baseline exists) the
  // day's reading, so they land together and can never disagree.
  | {
      type: "setTrackerSnapshot";
      id: ID;
      snapshot: JiraSnapshot;
      sample: TrackerSample | null;
    }
  | { type: "setTrackerSprintDraft"; id: ID; draft: SprintDraft | null }
  | { type: "markSprintItemsApplied"; id: ID; applied: SprintItemApplied[] };
